INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q108822189', 'Portuguese Oman', 'Portuguese Oman refers to the period during which the northern coastal cities of Oman were under Portuguese rule, between 1507 and 1656. The coastal region was conquered by Portuguese forces under the command of Afonso de Albuquerque in 1507, and remained under Portuguese control until they were expelled by the Ya''rubids.', 1507, NULL, NULL, 1656, NULL, NULL, 'year', '1507–1656', 30, 'https://en.wikipedia.org/wiki/Portuguese_Oman'),
  ('Q5037040', 'Capture of Muscat', 'The capture of Muscat occurred in 1552, when an Ottoman fleet under Piri Reis attacked Old Muscat, in modern Oman, and plundered the town from the Portuguese. These events followed the important Ottoman defeat in the third siege of Diu in 1546, which put a stop to their attempts in India, but also the successful capture of Aden in 1548, which allowed the Ottomans to resist the Portuguese in the northwestern part of the Indian Ocean.', 1552, 8, NULL, NULL, NULL, NULL, 'month', 'August 1552', 47, 'https://en.wikipedia.org/wiki/Capture_of_Muscat_(1552)'),
  ('Q111644445', 'Hamerton treaty', 'The Hamilton Treaty was a treaty signed between Britain and the Omani Empire in 1845. It was named after Atkins Hamerton, who negotiated the treaty on behalf of Britain.', 1845, NULL, NULL, NULL, NULL, NULL, 'year', '1845', 26, 'https://en.wikipedia.org/wiki/Hamerton_Treaty'),
  ('Q2363565', 'Dhofar Rebellion', 'The Dhofar rebellion, also known as the Dhofar War, or the 9 June revolution, was a revolution that began in 1965 in the Dhofar region of the Arabian Peninsula against British imperialism and Sultans Said ibn Taimur and Qaboos bin Said of the Al Bu Said dynasty in Oman. The conflict began with the formation of the Dhofar Liberation Front, a nationalist group which later adopted Marxism–Leninism and aimed to create a people''s democratic state in the Persian Gulf region.', 1963, 6, 9, 1976, 3, 11, 'day', '9 June 1963 – 11 March 1976', 57, 'https://en.wikipedia.org/wiki/Dhofar_rebellion'),
  ('Q48815086', '1970 Omani coup d''état', 'On 23 July 1970, Qaboos bin Said overthrew his father Said bin Taimur, the Sultan of Muscat and Oman. Occurring amid the Dhofar rebellion, the palace coup was executed by the British and saw Said deposed and sent into exile to the United Kingdom.', 1970, 7, 23, NULL, NULL, NULL, 'day', '23 July 1970', 41, 'https://en.wikipedia.org/wiki/1970_Omani_coup_d''%C3%A9tat'),
  ('Q2889338', 'Battle of Mirbat', 'The Battle of Mirbat (19 July 1972) was an attack by the Popular Front for the Liberation of the Occupied Arabian Gulf (PFLOAG) targeting an Omani government position in the town of Mirbat, Oman. During the Dhofar Rebellion, Britain assisted the Omani government, an absolute monarchy, by sending elements of its Special Air Service (SAS) both to train soldiers and fight against the PFLOAG guerrillas.', 1972, 7, 19, NULL, NULL, NULL, 'day', '19 July 1972', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mirbat'),
